examples.code:
text = "abc"
it = iter(text)
while True:
    try:
        print(next(it))
    except StopIteration:
        print("done")
        break

def countdown(n):
    while n > 0:
        yield n
        n -= 1

print(list(countdown(4)))
for number in countdown(3):
    print(number)

def read_lines(text):
    for line in text.splitlines():
        if line.strip():
            yield line.strip()

for line in read_lines('tea\n\ncoffee\n'):
    print(line)

